namespace Espo\ORM {
 class Entity { public array $values=[]; public function __construct(public string $id='',public string $type=''){} public function getId():string{return $this->id;} public function get(string $key):mixed{return $this->values[$key]??null;} public function set(array|string $key,mixed $value=null):void{if(is_array($key))$this->values=array_merge($this->values,$key);else $this->values[$key]=$value;} }
 class EntityManager { public array $rows=[];public bool $failCompletion=false;public int $seq=0;public function getEntityById(string $type,string $id):?Entity{return $this->rows[$type][$id]??null;}public function getNewEntity(string $type):Entity{return new Entity('entity'.(++$this->seq),$type);}public function saveEntity(Entity $e,array $options=[]):void{if($this->failCompletion&&$e->type==='MediaJob'&&$e->get('status')==='completed'){$this->failCompletion=false;throw new \RuntimeException('simulated database crash');}$e->values+=['createdAt'=>gmdate('Y-m-d H:i:s')];$this->rows[$e->type][$e->id]=$e;}public function getRDBRepository(string $type):FakeRepo{return new FakeRepo($this,$type);}public function getTransactionManager():FakeTx{return new FakeTx($this);} }
 class FakeTx {private array $snapshot=[];public function __construct(private EntityManager $em){}public function start():void{$this->snapshot=unserialize(serialize($this->em->rows));}public function commit():void{}public function rollback():void{$this->em->rows=$this->snapshot;} }
 class FakeRepo {private array $where=[];public function __construct(private EntityManager $em,private string $type){}public function where(array $q):self{$this->where=array_merge($this->where,$q);return $this;}public function find():array{return array_values(array_filter($this->em->rows[$this->type]??[],function($e){foreach($this->where as $f=>$v){if(str_ends_with($f,'>=')){if($e->get(substr($f,0,-2))<$v)return false;}elseif(is_array($v)){if(!in_array($e->get($f),$v,true))return false;}elseif($e->get($f)!==$v)return false;}return true;}));}public function findOne():?Entity{return $this->find()[0]??null;}public function count():int{return count($this->find());}public function order(...$x):self{return $this;}public function limit(...$x):self{return $this;} }
}
